package analyzer

import (
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"path/filepath"
	"strings"
	"testing"

	"golang.org/x/tools/go/analysis"
)

// TestCgoBoundary rejects the package once, retains a failure fact, and selects the original source.
func TestCgoBoundary(t *testing.T) {
	for _, reverse := range []bool{false, true} {
		positions := token.NewFileSet()
		dir := t.TempDir()
		source := filepath.Join(dir, "source", "main.go")
		inputs := []struct{ name, source string }{
			{filepath.Join(dir, "cache", "generated-d"),
				"// Code generated by cmd/cgo; DO NOT EDIT.\npackage sample\nimport \"unsafe\"\n"},
			{filepath.Join(dir, "work", "main.cgo1.go"), "// Code generated by cmd/cgo; DO NOT EDIT.\n" +
				"//line " + source + ":1:1\npackage sample\nimport _ \"unsafe\"\nimport _ \"unsafe\"\n"},
		}
		if reverse {
			inputs[0], inputs[1] = inputs[1], inputs[0]
		}
		var files []*ast.File
		for _, input := range inputs {
			file, err := parser.ParseFile(positions, input.name, input.source, parser.ParseComments)
			if err != nil {
				t.Fatal(err)
			}
			files = append(files, file)
		}
		checkCgoReport(t, positions, files, source)
	}
}

// checkCgoReport checks both the user-facing error and its dependency fact.
func checkCgoReport(t *testing.T, positions *token.FileSet, files []*ast.File, source string) {
	t.Helper()
	var reports []analysis.Diagnostic
	var fact *invalidPackage
	pass := &analysis.Pass{Pkg: types.NewPackage("sample", "sample"), Fset: positions, Files: files,
		TypesInfo: &types.Info{}, Report: func(d analysis.Diagnostic) { reports = append(reports, d) },
		ExportPackageFact: func(f analysis.Fact) { fact = f.(*invalidPackage) }}
	if _, err := run(pass); err != nil {
		t.Fatal(err)
	}
	if len(reports) != 1 || reports[0].Message != cgoDiagnostic {
		t.Fatalf("cgo diagnostics: %+v", reports)
	}
	if got := positions.Position(reports[0].Pos).String(); got != source+":1:1" {
		t.Fatalf("reported generated source: %s", got)
	}
	if fact == nil || fact.Origin != pass.Pkg.Path() || fact.Failure.Message != cgoDiagnostic {
		t.Fatalf("missing cgo dependency failure: %+v", fact)
	}
}

// TestCgoHeaderIsNotAnEscape keeps generated comments from granting trust to source.
func TestCgoHeaderIsNotAnEscape(t *testing.T) {
	cases := []struct {
		source string
		cgo    bool
	}{
		{"// Code generated by cmd/cgo; DO NOT EDIT.\npackage p", true},
		{"// Code generated by another tool; DO NOT EDIT.\npackage p", false},
		{"package p\n// Code generated by cmd/cgo; DO NOT EDIT.\n", false},
		{"package p\nimport \"C\"", true},
		{"package p\nimport `C`", true},
		{"package p\nimport _ \"unsafe\"", false},
	}
	for _, tc := range cases {
		positions := token.NewFileSet()
		file, err := parser.ParseFile(positions, "_cgo_gotypes.go", tc.source, parser.ParseComments)
		if err != nil {
			t.Fatal(err)
		}
		generated, imported := cgoFile(file)
		if got := generated || imported; got != tc.cgo {
			t.Fatalf("cgo=%t, want %t for %s", got, tc.cgo, tc.source)
		}
	}
}

// TestCgoKeepsDependencyFailures selects the first cause separately from relevance and local reports.
func TestCgoKeepsDependencyFailures(t *testing.T) {
	for _, origin := range []string{"example/bad", "example/zzz"} {
		t.Run(origin, func(t *testing.T) {
			positions := token.NewFileSet()
			file, err := parser.ParseFile(positions, "wrapper.go",
				"// Code generated by cmd/cgo; DO NOT EDIT.\npackage wrapper\n", parser.ParseComments)
			if err != nil {
				t.Fatal(err)
			}
			bad := types.NewPackage(origin, "bad")
			pkg := types.NewPackage("example/wrapper", "wrapper")
			pkg.SetImports([]*types.Package{bad})
			upstream := proofFailure{Location: origin + "/bad.go:1:1", Message: "invalid dependency"}
			var exported *invalidPackage
			var reports []analysis.Diagnostic
			pass := &analysis.Pass{Pkg: pkg, Fset: positions, Files: []*ast.File{file}, TypesInfo: &types.Info{},
				Report: func(d analysis.Diagnostic) { reports = append(reports, d) },
				ImportPackageFact: func(imported *types.Package, fact analysis.Fact) bool {
					if imported != bad {
						return false
					}
					*fact.(*invalidPackage) = *packageFailureFact(bad.Path(), true, nil, []proofFailure{upstream})
					return true
				},
				ExportPackageFact: func(fact analysis.Fact) { exported = fact.(*invalidPackage) },
			}
			if _, err := run(pass); err != nil {
				t.Fatal(err)
			}
			if len(reports) != 1 || reports[0].Message != cgoDiagnostic {
				t.Fatalf("cgo diagnostics: %+v", reports)
			}
			wantOrigin, wantFailure := origin, upstream
			if origin == "example/zzz" {
				wantOrigin = pkg.Path()
				wantFailure = proofFailure{Location: "example/wrapper/wrapper.go:2:1", Message: cgoDiagnostic}
			}
			if exported == nil || !exported.Relevant || exported.Origin != wantOrigin || exported.Failure != wantFailure {
				t.Fatalf("missing upstream cause or relevance: %+v", exported)
			}
			message := dependencyMessage(pkg.Path(), *roundTripFact(t, exported))
			if !strings.Contains(message, "run immutago "+wantOrigin+",") ||
				!strings.Contains(message, strings.ReplaceAll(wantFailure.Message, "\n", "\n  ")) {
				t.Fatalf("missing original package or failure: %s", message)
			}
		})
	}
}
